#[tokio::test]
async fn error_carries_code_and_reason() {
    let fake = Fake::start().await;
    let client = client(&fake).await;
    fake.push(Reply::Status {
        code: Code::InvalidArgument as i32,
        message: "no".to_string(),
        reason: Some((
            "INVALID_TIME_ZONE".to_string(),
            "freebusy.shokki.engineering".to_string(),
        )),
    });
    let err = client
        .availability()
        .compute_availability(
            ComputeAvailabilityRequest::new()
                .set_window(google_cloud_type::model::Interval::default()),
        )
        .await
        .unwrap_err();
    assert_eq!(err.code(), Code::InvalidArgument);
    assert!(err.is_reason(ErrorReason::InvalidTimeZone));
    assert_eq!(err.reason(), Some("INVALID_TIME_ZONE"));
    assert_eq!(err.domain(), Some("freebusy.shokki.engineering"));
}

